export type ParsedCollectTaxShareInstruction<
  TProgram extends string = typeof FAIR_OPEN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    programConfig: TAccountMetas[0];
    launch: TAccountMetas[1];
    vault: TAccountMetas[2];
    pot: TAccountMetas[3];
    quoteMint: TAccountMetas[4];
    treasury: TAccountMetas[5];
    coinRegistrar: TAccountMetas[6];
    feeConfig: TAccountMetas[7];
    coinRecord: TAccountMetas[8];
    feeClaimer: TAccountMetas[9];
    feeClaimerTokenAccount: TAccountMetas[10];
    poolAuthority: TAccountMetas[11];
    dbcConfig: TAccountMetas[12];
    pool: TAccountMetas[13];
    baseVault: TAccountMetas[14];
    quoteVault: TAccountMetas[15];
    mint: TAccountMetas[16];
    tokenBaseProgram: TAccountMetas[17];
    dbcEventAuthority: TAccountMetas[18];
    dbcProgram: TAccountMetas[19];
    feeEventAuthority: TAccountMetas[20];
    feeProgram: TAccountMetas[21];
    tokenProgram: TAccountMetas[22];
    systemProgram: TAccountMetas[23];
    eventAuthority: TAccountMetas[24];
    program: TAccountMetas[25];
  };
  data: CollectTaxShareInstructionData;
};

export function parseCollectTaxShareInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCollectTaxShareInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 26) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 26,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      programConfig: getNextAccount(),
      launch: getNextAccount(),
      vault: getNextAccount(),
      pot: getNextAccount(),
      quoteMint: getNextAccount(),
      treasury: getNextAccount(),
      coinRegistrar: getNextAccount(),
      feeConfig: getNextAccount(),
      coinRecord: getNextAccount(),
      feeClaimer: getNextAccount(),
      feeClaimerTokenAccount: getNextAccount(),
      poolAuthority: getNextAccount(),
      dbcConfig: getNextAccount(),
      pool: getNextAccount(),
      baseVault: getNextAccount(),
      quoteVault: getNextAccount(),
      mint: getNextAccount(),
      tokenBaseProgram: getNextAccount(),
      dbcEventAuthority: getNextAccount(),
      dbcProgram: getNextAccount(),
      feeEventAuthority: getNextAccount(),
      feeProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getCollectTaxShareInstructionDataDecoder().decode(instruction.data),
  };
}
